y = \arccos x,\quad x = 0,\quad y = 0 \\
\text{绕 } x \text{ 轴旋转一周，求体积 } V
\end{gathered}

solution:
\begin{gathered}
V = \pi\int_0^1 (\arccos x)^2\,dx \\
\xlongequal{x = \cos t} \pi\int_0^{\frac{\pi}{2}} t^2\sin t\,dt \\
= \pi\bigl[-t^2\cos t + 2t\sin t + 2\cos t\bigr]_0^{\frac{\pi}{2}} \\
= \pi^2 - 2\pi
\end{gathered}

